# Generated by Descant: acceptance tests below.

RSpec.describe Invoices::ReservationAdapters do
  # "This leaf adds and registers the adapter used when the owner is `:timekeeping`"
  it "answers the Timekeeping service owner with the remote reservation client" do
    ownership = TimekeepingOwnership.new(owner: "timekeeping", monolith_store: "prepared")
    expect(Timekeeping::EntryOwner.for(ownership)).to eq(:timekeeping)

    expect(described_class.for(ownership)).to be_a(Timekeeping::ReservationClient)
  end

  it "answers the Timekeeping owner with the client over the fake once a spec wires it, and that client's dropped answer is applied by the fake" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake_client = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    prepares_seen = 0
    http = timekeeping_answer_dropping_http(fake_client) do |_method, path|
      path.end_with?("/reservations/prepare") && (prepares_seen += 1) == 1
    end
    wired = use_fake_timekeeping_reservations(fake, http:)
    ownership = TimekeepingOwnership.new(owner: "timekeeping", monolith_store: "prepared", generation: fake.generation)
    request = Invoices::ReservationRequest.new(
      company_id: 77, invoice_id: 5, operation_id: SecureRandom.uuid,
      generation: fake.generation, disposition: "active", entries: []
    )

    adapter = described_class.for(ownership)

    expect(adapter).to be(wired)
    expect(adapter.prepare(request)).to have_attributes(state: "retryable", reason: "transport_error")
    expect(fake.requests.pluck(:path)).to eq(["/v1/companies/77/reservations/prepare"])
    # The fake stored the prepare whose answer was lost, so commit finds it.
    expect(adapter.commit(request).state).to eq("committed")
  end
end
